function duration(base:string,c:Cfg){const v=base.toLowerCase();if(v.includes('full day'))return c.full;if(v.includes('half day'))return c.half;if(v.includes('2 hour'))return c.h2;if(v.includes('3 hour'))return c.h3;if(v.includes('4 hour'))return c.h4;if(v.includes('flex'))return c.flex;return base;}
function cat(t:Trip,c:Cfg){const pair=t.category==='culture'?c.culture:t.category==='islands-snorkeling'?c.sea:t.category==='diving-sea'?c.dive:t.category==='desert-adventure'?c.desert:t.category==='family-city'?c.city:c.priv;const included=t.category==='culture'?c.incC:t.category==='islands-snorkeling'?c.incS:t.category==='diving-sea'?c.incD:t.category==='desert-adventure'?c.incA:t.category==='family-city'?c.incCity:c.incP;const bring=t.category==='culture'?c.bringC:t.category==='desert-adventure'?c.bringA:t.category==='family-city'?c.bringCity:t.category==='private'&&t.slug!=='private-boat'?c.bringC:c.bringS;return{pair,included,bring};}
export const remainingTripTranslations:RemainingTripTranslation[]=(Object.keys(cfg) as RemainingTripLocale[]).flatMap(locale=>{const c=cfg[locale];return trips.map(trip=>{const title=c.titles[trip.slug]??proper(trip.slug,trip.title);const shortDescription=c.desc(trip,title);const x=cat(trip,c);return{locale,slug:trip.slug,title,eyebrow:`${title} ${c.from}`,shortDescription,duration:duration(trip.duration,c),highlights:[{title:x.pair[0],description:x.pair[1]},{title:c.hotel,description:c.hotelD},{title:c.clear,description:c.clearD}],itinerary:[{title:c.hotel,description:c.hotelD},{title:c.main,description:shortDescription},{title:c.pause,description:c.pauseD},{title:c.back,description:c.backD}],included:x.included,excluded:c.exc,whatToBring:x.bring,whatsappMessage:`${c.wa} ${title} ${c.from}.`,seoTitle:`${title} ${c.from} | ToraMora`,seoDescription:shortDescription,isReviewed:false};});});
